<?php

declare(strict_types=1);

namespace YouWillLikeIT\Cleaning\DataObjects;

use SilverStripe\ORM\DataObject;
use SilverStripe\Security\Member;
use SilverStripe\Security\Permission;

/**
 * A zone / area within a CleaningObject assigned to one worker.
 *
 * QRToken is a 64-char hex string generated by GenerateRevirTokensTask.
 * Workers scan the QR code to create a RevirCheckIn proof-of-presence record.
 */
class Revir extends DataObject
{
    private static string $table_name    = 'Revir';
    private static string $singular_name = 'Revir';
    private static string $plural_name   = 'Revirs';

    /** @var array<string,string> */
    private static array $db = [
        'Name'       => 'Varchar(255)',
        'FloorArea'  => 'Decimal(8,2)',   // m²
        'Notes'      => 'Text',
        'QRToken'    => 'Varchar(64)',
        'IsActive'   => 'Boolean',
    ];

    /** @var array<string,string> */
    private static array $has_one = [
        'CleaningObject' => CleaningObject::class,
        'AssignedWorker' => Member::class,
    ];

    /** @var array<string,string> */
    private static array $has_many = [
        'CheckIns'    => RevirCheckIn::class,
        'Assignments' => WorkerAssignment::class,
        'Photos'      => AssignmentPhoto::class,
        'TimeEntries' => TimeTracking::class,
        'Ratings'     => ClientRating::class,
    ];

    /** @var array<string,string> */
    private static array $summary_fields = [
        'Name'                   => 'Name',
        'CleaningObject.Name'    => 'Object',
        'AssignedWorker.Name'    => 'Worker',
        'FloorArea'              => 'Area (m²)',
        'IsActive'               => 'Active',
    ];

    private static array $defaults = [
        'IsActive' => true,
    ];

    private static string $default_sort = 'CleaningObjectID ASC, Name ASC';

    /**
     * Return a URL-safe QR code link for this Revir.
     * Host app should route /cleaning/qr/{token} to RevirQRController.
     */
    public function getQRUrl(): string
    {
        return '/cleaning/qr/' . $this->QRToken;
    }

    // ── Permissions ───────────────────────────────────────────────────────

    public function canView(mixed $member = null): bool
    {
        if (Permission::checkMember($member, ['SUPER_ADMIN', 'COMPANY_ADMIN', 'AREA_MANAGER', 'ADMIN'])) {
            return true;
        }
        // Worker sees only their assigned revirs
        $user = \SilverStripe\Security\Security::getCurrentUser();
        return $user && (int) $this->AssignedWorkerID === (int) $user->ID;
    }

    public function canCreate(mixed $member = null, $context = []): bool
    {
        return Permission::checkMember($member, ['SUPER_ADMIN', 'COMPANY_ADMIN', 'ADMIN']);
    }

    public function canEdit(mixed $member = null): bool
    {
        return Permission::checkMember($member, ['SUPER_ADMIN', 'COMPANY_ADMIN', 'ADMIN']);
    }

    public function canDelete(mixed $member = null): bool
    {
        return Permission::checkMember($member, ['SUPER_ADMIN', 'COMPANY_ADMIN', 'ADMIN']);
    }
}
